WITH cleaned AS (SELECT *, CAST(amount AS INT) AS amount_int, TRIM(status) AS clean_status FROM payments WHERE order_id IS NOT NULL AND order_id IN (11, 34)), with_gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_burst FROM cleaned), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT CASE WHEN amount >= 1620 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, order_id, MIN(paid_at) AS first_paid_at, COUNT_IF(status = 'FAILED') AS failed_events, MAX(paid_at) AS last_paid_at, MAX(paid_at) AS ended_at, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS span_minutes, PERCENT_RANK() OVER (PARTITION BY CASE WHEN amount >= 1620 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY COUNT_IF(status = 'FAILED') DESC) AS failed_events_percent_rank FROM islands GROUP BY CASE WHEN amount >= 1620 THEN 'PREMIUM' ELSE 'STANDARD' END, order_id ORDER BY failed_events DESC;
